    private void parseConstraint(String entry) {
        int index = entry.indexOf(':');
        if (index < 0) {
            addDefaultConstraint(entry);
            return;
        }
        String type = entry.substring(0, index).trim();
        String value = entry.substring(index + 1).trim();

        switch (type.toLowerCase(Locale.ENGLISH)) {
            case "keysize":
                handleKeySize(value);
                break;
            case "denyafter":
                handleDenyAfter(value);
                break;
            default:
                addDefaultConstraint(type + ":" + value);
                break;
        }
    }

    private void addDefaultConstraint(String constraint) {
        String[] parts = constraint.split(":", 2);
        if (parts.length > 1) {
            String alg = parts[0].toLowerCase(Locale.ENGLISH);
            String val = parts[1];
            Set<Constraint> set = constraintsMap.computeIfAbsent(alg, k -> new HashSet<>());
            set.add(new DefaultConstraint(val));
        } else {
            constraintsMap.put(constraint, new HashSet<>());
        }
    }

    private void handleKeySize(String value) {
        Matcher matcher = keySizePattern.matcher(value);
        if (matcher.find()) {
            String op = matcher.group(1);
            int size = Integer.parseInt(matcher.group(2));

            Set<Constraint> set = constraintsMap.getOrDefault("keySize", new HashSet<>());
            set.add(new KeySizeConstraint(op, size));
            constraintsMap.put("keySize", set);
        }
    }

    private void handleDenyAfter(String value) {
        Matcher matcher = denyAfterPattern.matcher(value);
        if (matcher.find()) {
            int year = Integer.parseInt(matcher.group(1));
            int month = Integer.parseInt(matcher.group(2)) - 1;
            int day = Integer.parseInt(matcher.group(3)); // Note: group(3) does not exist

            Date date = new Date(year, month, day);
            Set<Constraint> set = constraintsMap.getOrDefault("denyAfter", new HashSet<>());
            set.add(new DenyAfterConstraint(date));
            constraintsMap.put("denyAfter", set);
        }
    }

    public boolean permits(Key key) {
        String algo = key.getAlgorithm();
        Set<Constraint> constraints = constraintsMap.getOrDefault(algo, Collections.emptySet());

        for (Constraint c : constraints) {
            if (!c.permits(key)) {
                return false;
            }
        }
        return true;
    }

    public void permits(CertConstraintParameters cp) throws CertPathValidatorException {
        X509Certificate cert = cp.getCertificate();
        String algo = cert.getSigAlgName();
        Set<Constraint> constraints = constraintsMap.getOrDefault(algo, Collections.emptySet());

        for (Constraint c : constraints) {
            if (!c.permits(cert)) {
                throw new CertPathValidatorException(
                        "Algorithm constraints check failed on constrained certificate",
                        null, null, -1, BasicReason.ALGORITHM_CONSTRAINED);
            }
        }
    }
