private abstract static class Constraint {
    abstract boolean permits(Object obj);
}

private static class KeySizeConstraint extends Constraint {
    private final String operator;
    private final int size;

    KeySizeConstraint(String operator, int size) {
        this.operator = operator;
        this.size = size;
    }

    @Override
    public boolean permits(Object obj) {
        if (!(obj instanceof Key)) {
            return false;
        }
        Key key = (Key) obj;
        int keySize = getKeySize(key);

        switch (operator.charAt(0)) {
            case '<':
                return keySize < size;
            case '>':
                return keySize > size;
            case '=':
                return keySize == size;
            case '!':
                return keySize != size;
            case '<=':
                return keySize <= size;
            case '>=':
                return keySize >= size;
            default:
                return false;
        }
    }

